#include <iostream>

int main() {
    int originalPayCode{0};
    if (std::cin >> originalPayCode) {
        int payCodeCorrect = originalPayCode;
        std::cout << "Initial payCode: " << payCodeCorrect << "\n";

        // Standard correct comparison
        if (payCodeCorrect == 4) {
            std::cout << "Bonus granted (correct equality)\n";
        } else {
            std::cout << "No bonus (correct equality)\n";
        }

        // Defensive comparison (Yoda condition)
        if (4 == payCodeCorrect) {
            std::cout << "Yoda check passed: payCode is 4\n";
        } else {
            std::cout << "Yoda check: payCode is not 4\n";
        }

        // Simulating the bug safely in an isolated variable
        int payCodeBuggy = originalPayCode;
        // Intended payCodeBuggy == 4, but mistakenly used =
        if ((payCodeBuggy = 4)) { 
            std::cout << "BUG: Condition evaluated to true! Mutated payCode: " 
                      << payCodeBuggy << "\n";
        }

        // Demonstrating discarded comparison statement
        int counter{10};
        counter == 20; // Evaluated and discarded, counter unchanged
        std::cout << "Counter after 'counter == 20;': " << counter << "\n";
    }
    return 0;
}

#include <iostream>

// Demonstrating Structured Program Composition (Stacking and Nesting)
int main() {
    int count{0};
    if (!(std::cin >> count)) {
        return 0;
    }

    // STACKED BLOCK 1: Input validation via single selection
    if (count < 1) {
        count = 1;
    }

    // STACKED BLOCK 2: Repetition containing nested selection structures
    // Outer block: for loop (Repetition)
    for (int i = 1; i <= count; ++i) {
        std::cout << "Item " << i << ": ";

        // NESTED BLOCK: double selection (if...else) inside for loop
        if (i % 2 == 0) {
            std::cout << "Even";
        } else {
            std::cout << "Odd";
        }

        // NESTED BLOCK: switch (multiple selection) nested within loop
        switch (i) {
            case 1:
                std::cout << " [First]";
                break;
            case 3:
                std::cout << " [Target]";
                break;
            default:
                break;
        }
        std::cout << "\n";
    }

    // STACKED BLOCK 3: Final action state before exit
    std::cout << "Processing complete.\n";
    return 0;
}
